// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 duration, uint256 strike, uint256 expiration) public {
        // keep duration admissible and non-zero
        duration = bound(duration, 1, 10_000 days - 1);
        strike = bound(strike, 0, 1e30);
        vm.warp(1_000_000);
        uint256 ts = block.timestamp;
        expiration = bound(expiration, ts + 1, ts + 365 days);

        // adversarial counterparties deployed as helpers:
        //  - Signer: an ERC1271 contract that acts as the order maker (validates any signature)
        //  - FakeToken: a baseAsset contract whose transferFrom/approve always succeed
        Signer maker = new Signer();
        FakeToken token = new FakeToken();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = new bytes(0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 orderHash = uint256(c.hashOrder(order));
        // for a long order the key holding the expiration is the order hash itself
        uint256 storedExpiration = c.positionExpirations(orderHash);

        // GENERAL RULE: for any admissible order, the stored position expiration
        // equals fill time plus the order duration (hence is strictly in the future).
        assertTrue(storedExpiration == ts + duration, "expiration must be fill time + duration");
    }
}

/// ERC1271 signer used as order.maker: accepts any signature.
contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

/// Minimal always-succeeding baseAsset token.
contract FakeToken {
    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
